def get_max_level_nested_paren_string(parens: str) -> int:
    """
    Helper function to compute maximum level of nesting from a single string.

    :param parens: string representation of a single group of nested parentheses
    :return: maximum nesting level (highest level of nested parentheses)
    """
    stack = [1]
    curr_level = 0
    for char in parens:
        if char == '(':
            stack.append(curr_level + 1)
        elif char == ')':
            stack.pop()
            curr_level = stack[-1] if stack else 0

    return max(stack)


