    """ Input to this function is a string represented the result of paren_string. E.g. if paren_string = 
    ((())(()())()(())(())()), evaluate_paren_string will output the value 21 as 6 + 1 + 4 + 10.

    >>> evaluate_parens('(()()) ((())) () ((())()())')
    21
    """
    result = 0
    current_sum = 0
    for character in paren_string:
        if character == '(':
            current_sum += 1
        elif character == ')':
            result += current_sum
            current_sum = 0
    return result


