def is_balanced(paren_string: str) -> bool:
    """
    Given a string containing multiple groups of nested parentheses, this function will tell whether they are all balanced.
    Balanced groups have the same number of opening and closing parentheses
    >>> is_balanced('(()())')
    True
    """
    count_open = 0
    for character in paren_string:
        if character == '(':
            count_open += 1
        if character == ')':
            count_open -= 1
        if count_open < 0:
            return False
    return count_open == 0


