        """Initialize a Rectangle with the given length and width."""
        self.length = length
        self.width = width

    def get_area(self):
        """Return the area of this rectangle."""
        return self.length * self.width

    def get_perimeter(self):
        """Return the perimeter of this rectangle."""
        return 2 * (self.length + self.width)

    def get_diagonal(self):
        """Return the length of the diagonal of this rectangle."""
        return ((self.length ** 2 + self.width ** 2) ** 0.5)

    def get_picture(self):
        """Return a string representation of this Rectangle according to size rules."""
        if self.length > 50 or self.width > 50:
